        forbidden = blocked.get(name, ())
        for row in packages[name]:
            version = row['version']
            if version in forbidden or not minimum <= version <= maximum:
                continue
            if name in pins and version != pins[name]:
                continue

            next_constraints = dict(constraints)
            valid = True
            for dependency in row.get('deps', []):
                dep_name = dependency['name']
                dep_min = dependency['min']
                dep_max = dependency['max']
                if dep_name in next_constraints:
                    old_min, old_max = next_constraints[dep_name]
                    next_constraints[dep_name] = (
                        max(old_min, dep_min), min(old_max, dep_max)
                    )
